# SPDX-License-Identifier: AGPL-3.0-or-later
"""Graceful failure + an autogenerated, user-editable bug report.

When something goes wrong, localm should fail like a good citizen: say *what*
broke and *why* in plain language, then offer to send a prefilled report the
user can read and edit before anything leaves their machine.

Channels, in the order that actually works for a tester:
  * **hosted send** (`--send`, or menu [1]) - uploads through the account-less
    Cloudflare Worker proxy, which files the GitHub issue server-side. No
    GitHub account, ever - this is the only channel that actually creates an
    issue automatically. See the "Upload channel" section below.
  * **email** - opens the user's mail app prefilled to the maintainer. Works for
    anyone, including a tester on a still-private repo.
  * **do it yourself** - the report is always saved to a file, so the user can
    drop it on Discord, paste it, or attach it however they like.

There is deliberately NO "open a GitHub issue in your browser" channel: that
would ask a tester to sign in to (and have access to) a private repo, exactly
the friction the hosted channel exists to remove. Anyone who genuinely wants to
file it on github.com themselves still can, by hand, outside the app.

The maintainer's contact email is intentionally published here for bug reports
(the maintainer opted in); see scripts/check_hygiene.py.

Diagnostics aim to be *actually useful* - the data a maintainer needs to act on a
report - while staying safe:
  * OS / arch / Python, GPU vendor + NVIDIA driver / CUDA capability, the chosen
    and recommended backend, and the *names* of provisioned native libraries.
  * App state: the loaded model, effective backend, context ceiling, session
    (privacy) mode, debug flag, and enabled plugins.
  * An ALLOWLISTED, scrubbed subset of config (context sizing, ports, media URLs,
    privacy mode) - never the whole config, so a future secret-bearing key cannot
    leak; path values are home-scrubbed and URL values credential-scrubbed.
  * Versions of the dependencies that shape a failure (native runtime, HF + server
    stacks).
  * The in-memory recent-activity log (INFO+ breadcrumbs; the raw model output is
    DEBUG-level, so chat content never enters it) and, for a GUI report, the
    browser context + recent JS console errors.

What is NEVER collected: the API key, environment variables (which can hold one),
config secrets, the raw chat/transcript content, or anything written only at DEBUG
level. The user also reviews and edits the report before sending, regardless.
"""

from __future__ import annotations

import platform
import re
import sys
import threading
import traceback
import urllib.parse
import webbrowser
from pathlib import Path
from typing import Optional

from rich.console import Console

from localm import pathscrub

console = Console(highlight=False)

# Intentionally published maintainer contact for bug reports (hygiene-ok).
MAINTAINER_EMAIL = "theilige@gmail.com"

# A mailto body cannot be arbitrarily long (mail clients and some browsers
# truncate very long query strings), so the prefilled body is a short pointer and
# the full detail lives in the saved file the user attaches or pastes.
_MAX_PREFILL_BODY = 1500


class LocalmError(Exception):
    """A user-facing, reportable failure.

    Raise this (not a bare Exception) when a command hits a known, describable
    problem. The CLI's single graceful handler turns it into a "sorry, X went
    wrong because Y" message and offers a bug report - the command that raises it
    knows nothing about reporting. Carries a human *summary*, an optional
    *reason*, and diagnostic *context* for the report."""

    def __init__(self, summary: str, reason: str = "",
                 context: Optional[dict] = None, *,
                 stage: Optional[str] = None, hint: Optional[str] = None):
        super().__init__(summary)
        self.summary = summary
        self.reason = reason
        self.context = context or {}
        # For an UPLOAD failure: WHERE it failed (offline_or_dns / unreachable /
        # tls / timeout / server_rejected / no_endpoint / rate_limited / unknown)
        # and a friendly, actionable *hint* to show the user. Both None for a
        # non-upload LocalmError.
        self.stage = stage
        self.hint = hint


class RateLimitedError(LocalmError):
    """The bug-report proxy returned HTTP 429 (rate limited). Carries *retry_after*
    (seconds) so a caller can wait and retry once instead of failing outright. A
    subclass of LocalmError, so existing ``except LocalmError`` handlers still treat
    it as a (non-fatal) send failure; callers that want the retry catch it first."""

    def __init__(self, retry_after: int = 30, reason: str = ""):
        try:
            ra = max(1, int(retry_after))
        except (TypeError, ValueError):
            ra = 30
        super().__init__("the bug-report server is rate limiting reports",
                         reason=reason or f"try again in about {ra} seconds",
                         context={"retry_after": ra},
                         stage="rate_limited",
                         hint=(f"The bug-report server is busy right now and asked to "
                               f"wait about {ra}s before trying again. Your report is "
                               f"saved either way."))
        self.retry_after = ra


def _localm_version() -> str:
    # Live VERSION-file read (falls back to installed metadata): the install is
    # editable, so a code-only update changes VERSION without refreshing dist-info.
    try:
        from localm._version import read_version
        return read_version()
    except Exception:
        return "unknown"


def _runtime_libs() -> tuple:
    """(binary_dir or None, sorted list of native library file NAMES present).
    Names only - never full paths beyond the resolved dir, never contents."""
    try:
        from localm.inference.backends.llamacpp._loader import (
            lib_filename, runtime_binary_dir)
        d = runtime_binary_dir()
        if d is None:
            return None, []
        # Load-bearing shared libraries only - the bundled llama-*.exe tools are
        # noise in a report (dozens of them) and not relevant to a load failure.
        names = sorted(
            f.name for f in Path(d).iterdir()
            if f.is_file() and (f.suffix.lower() in (".dll", ".so", ".dylib")
                                or ".so." in f.name)
        )
        return d, names, lib_filename()
    except Exception:
        return None, [], ""


def collect_diagnostics(context: Optional[dict] = None) -> dict:
    """Gather a safe, useful environment snapshot. Never raises."""
    context = dict(context or {})
    diag: dict = {}
    try:
        diag["localm_version"] = _localm_version()
        diag["python"] = sys.version.split()[0]
        diag["platform"] = platform.platform()
        diag["machine"] = platform.machine()
    except Exception:
        # Best-effort: collect_diagnostics must never raise (it runs ON the
        # failure path). A problem here just omits these basic fields; the rest
        # of the snapshot is gathered by the independently guarded blocks below.
        pass

    try:
        from localm import hwdetect
        det = hwdetect.detect()
        diag["gpu_vendors"] = det.vendors or []
        # recommended_install_backend, NOT det.recommended. The latter is the
        # blanket "vulkan whenever any GPU is present" value, so a report from an
        # NVIDIA-on-Windows box said "Recommended backend: vulkan" while the
        # installer's actual policy for it is cuda (#765) and the box was in fact
        # running the CUDA runtime. A diagnostics field that contradicts what the
        # installer would provision sends triage after the wrong thing; it did
        # exactly that on #833. det.recommended keeps its own meaning for its
        # other callers (updater, release_verify) and is untouched.
        diag["recommended_backend"] = hwdetect.recommended_install_backend(det)
        diag["detect_source"] = det.source
    except Exception:
        diag["gpu_vendors"] = []

    # NVIDIA driver / CUDA capability, when an NVIDIA GPU is involved.
    try:
        from localm.setup_llama import nvidia_preflight
        if "nvidia" in diag.get("gpu_vendors", []) or context.get("backend") == "cuda":
            nv = nvidia_preflight()
            if nv.present:
                diag["nvidia_gpu"] = nv.gpu_name
                diag["nvidia_driver"] = nv.driver_version
                diag["nvidia_cuda_capability"] = nv.cuda_capability
                diag["nvidia_compute_capability"] = nv.compute_capability
                diag["nvidia_cuda_line"] = nv.cuda_line
    except Exception:
        # Best-effort: probing the NVIDIA driver/CUDA capability is optional
        # detail. If it fails (no nvidia-smi, a driver hiccup) the report simply
        # omits these fields; never break report generation over it.
        pass

    try:
        res = _runtime_libs()
        binary_dir = res[0]
        names = res[1]
        diag["native_runtime_provisioned"] = binary_dir is not None
        diag["native_libs"] = names
    except Exception:
        # Best-effort: listing provisioned native libraries is diagnostic detail.
        # A failure (runtime dir missing, unreadable) just omits the names; the
        # report is still useful without them.
        pass

    # Caller-supplied context (chosen backend, the operation, etc.).
    for k in ("operation", "backend", "requested_backend", "with_cudart"):
        if k in context:
            diag[k] = context[k]

    # App / runtime state - the "what was the app actually doing" half of a useful
    # report. Each collector is independently guarded and returns empty on failure,
    # so a missing piece never costs the rest of the report.
    diag["loaded_model"] = _loaded_model_info()
    diag.update(_runtime_state())          # session_mode, debug_mode
    diag["enabled_plugins"] = _enabled_plugins()
    diag["config_subset"] = _safe_config_subset()
    diag["dependencies"] = _dependency_versions()
    return diag


# The home/username policy itself lives in localm.pathscrub, so the report
# scrubber and the API-response scrubber (embedder status, /debug/stacks) cannot
# drift apart - a copy of a privacy rule is a copy that gets fixed once. The
# behaviour here is unchanged: replace Path.home() with "~" in both separator
# forms (case-insensitively on Windows, AUD-SCRUBHOME), and ALWAYS apply the
# known-home-root username strip as a backstop so a path that is not exactly
# Path.home() - a different account - is caught too.
#
# A report deliberately keeps the INSTALL dir (pathscrub.scrub_paths would drop
# it): the maintainer reading the report needs to know where the app is
# installed. Responses to a lower-privileged caller use scrub_paths instead.
_scrub_home = pathscrub.scrub_user_paths


def _scrub_url_creds(text: str) -> str:
    """Strip ``user:pass@`` credentials from any URL-ish value before it goes in a
    report (a SearXNG / ComfyUI / reviewer URL can carry an inline secret)."""
    if not text:
        return text
    return re.sub(r"(://)[^/@\s]+@", r"\1<redacted>@", text)


# Bearer tokens ("Authorization: Bearer <token>") and API keys (OpenAI-style
# sk-..., or a localm key) can appear in a pasted console error, a fetch log
# line, or a mistyped config value. A bug report is share-intended, so strip
# them defensively even though no current code path is known to log a token
# (AUD-CLIENTSCRUB, defence in depth).
_BEARER_RE = re.compile(r"(?i)(bearer\s+)[A-Za-z0-9._\-]{8,}")
_APIKEY_RE = re.compile(r"(?i)\b(?:sk|localm[_-]sk)-[A-Za-z0-9._\-]{12,}")


def _scrub_secrets(text: str) -> str:
    """Run every scrubber over untrusted text: home paths (username), URL
    ``user:pass@`` credentials, and bearer / API-key tokens. Used for
    client-supplied fields and the bundled log tails / activity ring a
    share-intended report carries - each of which is untrusted, free-form text
    that could contain a secret the plain home-scrub alone would leave in."""
    if not text:
        return text
    text = _scrub_home(text)
    text = _scrub_url_creds(text)
    text = _BEARER_RE.sub(r"\1<redacted>", text)
    text = _APIKEY_RE.sub("<redacted>", text)
    return text


# Config keys SAFE to echo into a report and useful for debugging a setup. An
# allowlist (never the whole config) so a future secret-bearing key cannot be
# auto-leaked; path-like values are home-scrubbed and URL-like values
# credential-scrubbed before they are rendered. The API key lives in auth.key,
# never config.json - we stay conservative regardless.
_SAFE_CONFIG_KEYS = (
    "binary_dir", "n_ctx", "n_ctx_max", "ctx_auto", "n_gpu_layers",
    "n_gpu_layers_auto", "max_tokens",
    "model_swap_policy", "idle_unload_seconds", "reload_llm_after_imagine",
    "port", "require_auth", "cors_origins", "mode", "chat_mode", "coder_mode",
    "net_mode", "comfy_launch_cmd", "comfy_workdir", "comfy_api_url",
    "net_search_url", "coder_reviewer", "coder_review", "voice_stt_model",
)

# Distributions whose versions actually shape a localm failure. Optional / absent
# packages are simply skipped, so this stays correct across install profiles.
_REPORTED_DISTS = (
    "localm", "localm-llama-runtime", "llama-cpp-python", "torch", "transformers",
    "huggingface-hub", "fastapi", "uvicorn", "ctranslate2", "faster-whisper",
)


def _loaded_model_info() -> dict:
    """Snapshot of the in-process inference engine (model, backend, loaded?, ctx).

    Empty when no server engine is loaded in THIS process (e.g. a CLI
    ``bug-report``) or it cannot be read. Never raises."""
    try:
        from localm.inference import http_server as hs
        eng = getattr(hs, "_engine", None)
        if eng is None:
            return {}
        info: dict = {
            "model": getattr(eng, "display_name", "") or "(unnamed)",
            "loaded": bool(getattr(eng, "loaded", False)),
        }
        backend = getattr(eng, "_backend", None)
        if backend is not None:
            info["backend"] = type(backend).__name__
        ctx = getattr(eng, "effective_ctx_max", None)
        if ctx:
            info["effective_ctx_max"] = ctx
        return info
    except Exception:
        return {}


def _runtime_state() -> dict:
    """Session mode + debug flag. These explain WHY a report may carry little
    history (privacy mode writes nothing; a non-debug run keeps no log file), so
    they are diagnostic in their own right. Never raises."""
    state: dict = {}
    try:
        from localm.audit import effective_mode
        state["session_mode"] = effective_mode("server").value
    except Exception:
        # Best-effort diagnostic: if the session mode cannot be read the report
        # just omits it. This is a status readout, NOT the privacy-mode gate that
        # protects session writes, so omitting it weakens no privacy guarantee.
        pass
    try:
        from localm.debuglog import debug_enabled
        state["debug_mode"] = bool(debug_enabled())
    except Exception:
        # Best-effort diagnostic: omitting the debug flag from the report is
        # harmless; never raise from this collector.
        pass
    return state


def _enabled_plugins() -> list:
    """Names of enabled engine plugins, from config. Never raises."""
    try:
        from localm.config import load_config
        pl = load_config().get("plugins_enabled", [])
        return [str(p) for p in pl] if isinstance(pl, list) else []
    except Exception:
        return []


def _safe_config_subset() -> dict:
    """An allowlisted, scrubbed slice of the user config: enough to debug a setup
    problem (context sizing, ports, media URLs, privacy mode) without any secret.
    Never raises."""
    try:
        from localm.config import load_config
        cfg = load_config()
    except Exception:
        return {}
    out: dict = {}
    for key in _SAFE_CONFIG_KEYS:
        if key not in cfg:
            continue
        val = cfg[key]
        if isinstance(val, str) and val:
            val = _scrub_url_creds(_scrub_home(val))
        out[key] = val
    return out


def _dependency_versions() -> dict:
    """Versions of the packages that shape a localm failure (native runtime, HF
    stack, server stack). Absent packages are omitted. Never raises."""
    out: dict = {}
    try:
        from importlib.metadata import PackageNotFoundError, version
    except Exception:
        return out
    for dist in _REPORTED_DISTS:
        try:
            out[dist] = version(dist)
        except PackageNotFoundError:
            continue
        except Exception:
            continue
    return out


def _format_error(error: Optional[BaseException]) -> str:
    if error is None:
        return ""
    tb = "".join(traceback.format_exception(type(error), error, error.__traceback__))
    # Full scrub, not just home paths: an exception message can embed a
    # user-configured credentialed URL (a comfy_api_url / net_search_url / remote
    # server base with user:pass@) or a pasted token, and this traceback ships in the
    # uploaded "Error detail" body. _scrub_secrets adds the url-creds + bearer/apikey
    # strips the sibling log-tail already applies (HON-15; do not report a scrub the
    # module docstring promises but did not perform).
    tb = _scrub_secrets(tb)
    # Keep the tail - the last frames are the useful ones, and a shorter report
    # is more likely to be read and sent.
    lines = tb.strip().splitlines()
    if len(lines) > 25:
        lines = ["... (earlier frames trimmed) ..."] + lines[-24:]
    return "\n".join(lines)


# Outer safety cap on how much of the raw log FILE is even read before digesting -
# a per-run debug log is not expected to reach this, but a pathological long-lived
# run must not make digest-building read (and regex-scan) an unbounded file.
_LOG_TAIL_READ_BYTES = 2_000_000


def _recent_log_tail(home=None, pid=None, max_chars: int = 6000) -> str:
    """A digest of the crashed run's OWN log, matched by the pid embedded in the
    log filename (localm_<date>_<time>_<pid>.log): EVERY warning/error (with its
    full traceback) from the whole run, with runs of near-duplicate benign lines
    (e.g. routine ``GET /api/stats`` polling) collapsed to one line + a repeat
    count - see localm/_log_digest.py. A blind last-N-lines tail used to miss the
    actual failure whenever enough routine activity followed it before the report
    was filed (#617); this survives that regardless of how long the session ran
    afterward. Home paths are scrubbed. Never raises."""
    try:
        from pathlib import Path as _P
        if home is None:
            from localm.debuglog import logs_dir
            d = logs_dir()
        else:
            d = _P(home) / "logs"
        if not d.is_dir():
            return ""
        logs = sorted(d.glob("*.log"), key=lambda p: p.stat().st_mtime, reverse=True)
        chosen = None
        if pid is not None:
            for p in logs:
                if p.stem.endswith(f"_{pid}"):
                    chosen = p
                    break
        if chosen is None:
            # No pid match (older marker): fall back to the most recent log that is
            # NOT this current run's, so we do not just echo the recovering start.
            import os as _os
            cur = f"_{_os.getpid()}.log"
            chosen = next((p for p in logs if not p.name.endswith(cur)), None)
        if chosen is None:
            return ""
        raw = chosen.read_text(encoding="utf-8", errors="replace")
        if len(raw) > _LOG_TAIL_READ_BYTES:
            raw = raw[-_LOG_TAIL_READ_BYTES:]
        from localm._log_digest import build_digest
        return _scrub_secrets(build_digest(raw, max_chars=max_chars))
    except Exception:
        return ""


# A hang trace older than this cannot plausibly belong to the run being reported,
# whatever pid it carries (pids are reused - see REG-586). Generous on purpose: the
# pid match below is the precise filter, and this only backstops a pid collision.
_HANG_TRACE_MAX_AGE_S = 24 * 3600


def _recent_hang_traces(home=None, max_chars: int = 8000, *, pid=None) -> str:
    """The event-loop hang trace captured by the run being reported
    (``<logs>/hang_<date>_<pid>.log``), if the always-on stall watchdog captured
    one - every thread's stack at the moment the server froze, which is exactly
    what diagnoses an intermittent "it hung" report. Kept HEAD-first (the first
    snapshot names where the loop first stuck). Home paths are scrubbed. Empty
    when that run captured no freeze. Never raises.

    Matched to *pid* - the run this report is about - the same way
    _recent_log_tail already matches its log, and additionally bounded by
    _HANG_TRACE_MAX_AGE_S. Both filters are needed and neither is enough alone:

      * The watchdog is ON by default, so any transient >10s stall (a big index
        build, VRAM pressure) writes a trace, and nothing ever prunes them. With
        no filter, an ordinary report about something else entirely ("the model
        gave a wrong answer") attached whatever freeze happened to be newest -
        rendered under "## Server hang trace" asserting "the server froze",
        i.e. a stale, unrelated trace presented as the diagnosis of the current
        problem, sending triage down a false path (REG-542).
      * A pid alone is not an identity (pids get reused), so an ancient trace
        carrying this run's pid would still slip through; the age bound stops it.
      * Age alone is not enough either: a recent freeze in a DIFFERENT localm
        instance is not this report's problem; the pid match stops that.

    A caller that cannot name the run (no pid) gets nothing rather than a guess:
    attaching a trace we cannot tie to the report is the whole defect."""
    try:
        import time as _time
        from pathlib import Path as _P
        if home is None:
            from localm.debuglog import logs_dir
            d = logs_dir()
        else:
            d = _P(home) / "logs"
        if not d.is_dir() or pid is None:
            return ""
        cutoff = _time.time() - _HANG_TRACE_MAX_AGE_S
        traces = sorted(
            (p for p in d.glob(f"hang_*_{pid}.log") if p.stat().st_mtime >= cutoff),
            key=lambda p: p.stat().st_mtime, reverse=True)
        if not traces:
            return ""
        text = traces[0].read_text(encoding="utf-8", errors="replace").strip()
        if not text:
            return ""
        scrubbed = _scrub_secrets(text)
        if len(scrubbed) > max_chars:
            scrubbed = scrubbed[:max_chars] + \
                "\n... (trace truncated - full stacks in the hang_*.log file)"
        return scrubbed
    except Exception:
        return ""


def live_server_hang_trace(home=None) -> str:
    """The event-loop hang trace captured by a LIVE server of this install, for a
    user-initiated ``localm bug-report`` filed from a SEPARATE process (REG-736).

    The two in-process collectors each feed _recent_hang_traces a pid they already
    know: ``save_user_report`` (GUI) matches its own ``getpid()`` because the GUI IS
    the server, and crash recovery matches the crashed run's marker pid. The
    ``localm bug-report`` CLI has neither - it is its OWN short-lived process, whose
    pid never wrote a hang trace, while the frozen server is a DIFFERENT process
    still running. So a pid-of-self match (what the other paths do) finds nothing,
    and the report ships WITHOUT the one diagnostic the feature exists to deliver.

    Instead we look the server up in the live instance registry
    (``<home>/run/*.json``), keep only entries whose pid is actually alive, and
    return that server's pid-matched trace - the SAME pid-scoped _recent_hang_traces
    collection the crash path uses, just sourced from the live registry rather than
    a crash marker. With more than one live server, the most recently started one
    wins: a single, stable choice (build_report renders one hang-trace section).
    Empty when no live server captured a freeze. Never raises - a registry hiccup
    must not break filing a bug report."""
    try:
        from localm import instances
        if home is None:
            from localm.config import HOME_DIR
            home = HOME_DIR
        entries = sorted(instances.list_entries(home),
                         key=lambda e: e.get("started") or "", reverse=True)
        for entry in entries:
            pid = entry.get("pid")
            if not isinstance(pid, int) or not instances.pid_alive(pid):
                continue
            trace = _recent_hang_traces(home, pid=pid)
            if trace:
                return trace
        return ""
    except Exception:
        return ""


def _kv_lines(d: dict) -> list:
    """Render a flat dict as ``- key: value`` markdown lines (stable order)."""
    lines = []
    for k, v in d.items():
        if isinstance(v, list):
            v = ", ".join(str(x) for x in v) if v else "(none)"
        elif isinstance(v, bool):
            v = "yes" if v else "no"
        lines.append(f"- {k}: {v}")
    return lines


def _app_state_lines(diag: dict) -> list:
    """The "what the app was doing" half of the report: loaded model, effective
    backend, session mode, debug state, and enabled plugins."""
    lines = []
    lm = diag.get("loaded_model") or {}
    if lm:
        loaded = "loaded" if lm.get("loaded") else "NOT loaded"
        line = f"- Model: {lm.get('model', '(unnamed)')} ({loaded})"
        if lm.get("backend"):
            line += f", backend {lm['backend']}"
        if lm.get("effective_ctx_max"):
            line += f", ctx<={lm['effective_ctx_max']}"
        lines.append(line)
    else:
        lines.append("- Model: (no engine loaded in this process)")
    if "session_mode" in diag:
        lines.append(f"- Session mode: {diag['session_mode']}")
    if "debug_mode" in diag:
        lines.append(f"- Debug logging: {'on' if diag['debug_mode'] else 'off'}")
    plugins = diag.get("enabled_plugins")
    if plugins is not None:
        lines.append(f"- Enabled plugins: {', '.join(plugins) if plugins else '(none)'}")
    return lines


def build_report(summary: str, reason: str = "",
                 error: Optional[BaseException] = None,
                 context: Optional[dict] = None) -> str:
    """Render an editable markdown bug report. The user owns it before sending."""
    # The user-typed summary/reason are the only report fields not otherwise
    # scrubbed; a home path (username) or pasted credential in them would ship in
    # the uploaded body - and, via the derived title, into a PUBLIC issue. Scrub at
    # this choke point so every caller (report_failure, save_user_report) is covered
    # (HON-03/HON-15; AGENTS.md rule 5: a privacy step must not report a scrub it
    # did not do). _scrub_secrets is idempotent and no-ops on empty text.
    summary = _scrub_secrets(summary)
    reason = _scrub_secrets(reason)
    diag = collect_diagnostics(context)
    err = _format_error(error)

    env_lines = []
    label = {
        "localm_version": "localm", "python": "Python", "platform": "OS",
        "machine": "Arch", "gpu_vendors": "GPU vendor(s)",
        "recommended_backend": "Recommended backend", "detect_source": "Detected via",
        "nvidia_gpu": "NVIDIA GPU", "nvidia_driver": "NVIDIA driver",
        "nvidia_cuda_capability": "Driver CUDA capability",
        "nvidia_compute_capability": "GPU compute capability",
        "nvidia_cuda_line": "Selected CUDA line",
        "native_runtime_provisioned": "Native runtime provisioned",
        "native_libs": "Native libraries", "operation": "Operation",
        "backend": "Backend (effective)", "requested_backend": "Backend (requested)",
        "with_cudart": "Fetched CUDA runtime bundle",
    }
    for key, name in label.items():
        if key in diag:
            val = diag[key]
            if isinstance(val, list):
                val = ", ".join(str(x) for x in val) if val else "(none)"
            env_lines.append(f"- {name}: {val}")

    parts = [
        f"# localm bug report: {summary}",
        "",
        "## What I was doing",
        "<!-- Please describe what you ran and what you expected. -->",
        "",
        "## What happened",
        summary + ((f"\n\nReason: {reason}") if reason else ""),
        "",
        "## App state",
        "\n".join(_app_state_lines(diag)),
        "",
        "## Environment",
        "\n".join(env_lines) if env_lines else "(could not collect environment)",
    ]

    config_subset = diag.get("config_subset") or {}
    if config_subset:
        parts += ["", "## Configuration (safe subset)", "\n".join(_kv_lines(config_subset))]
    deps = diag.get("dependencies") or {}
    if deps:
        parts += ["", "## Dependencies", "\n".join(_kv_lines(deps))]

    if err:
        parts += ["", "## Error detail", "```", err, "```"]
    # Crash diagnostics passed via context (e.g. recovered-crash reports, which have
    # no Python error object). Without these the report is contentless (BUG-1): a
    # faulthandler native trace when one was captured, and the crashed run's own log
    # tail (the actionable bit when a window-close/OS-kill left no trace). Both are
    # already home-scrubbed at their source.
    ctx = context or {}
    native = ctx.get("native_trace")
    if native:
        parts += ["", "## Native fault trace", "```", _scrub_home(str(native))[:4000], "```"]
    tail = ctx.get("recent_log_tail")
    if tail:
        parts += ["", "## Recent log (tail)", "```", _scrub_home(str(tail))[:4000], "```"]
    hang = ctx.get("hang_traces")
    if hang:
        parts += ["", "## Server hang trace (event-loop stall)",
                  "The hang watchdog captured every thread's stack when the server "
                  "froze (the top of the main thread is the blocking call):",
                  "```", _scrub_home(str(hang))[:8000], "```"]

    # Always-on in-memory breadcrumbs (INFO+; no chat content) so even a non-debug
    # report shows what the app was doing right before the problem.
    ring = _ring_activity()
    if ring:
        parts += ["", "## Recent activity (in-memory log)", "```",
                  _scrub_secrets("\n".join(ring[-80:]))[-4000:], "```"]

    # Browser/client context for a GUI-filed report (user agent, page, viewport,
    # and recent JS console errors). Already a plain dict from the GUI; scrubbed
    # for home paths defensively.
    client = ctx.get("client")
    if isinstance(client, dict) and client:
        parts += ["", "## Browser / client"] + _client_lines(client)

    parts += [
        "",
        "---",
        f"Sent to the localm maintainer ({MAINTAINER_EMAIL}). "
        "You can edit anything above before sending.",
        "",
    ]
    return "\n".join(parts)


def _ring_activity() -> list:
    """The in-memory recent-activity buffer, or [] if unavailable. Never raises."""
    try:
        from localm.debuglog import recent_activity
        lines = recent_activity()
        try:
            from localm.config import home_dir
            pre_log = home_dir() / "logs" / "pre_restart.log"
            if pre_log.exists():
                lines = pre_log.read_text(encoding="utf-8").splitlines() + ["--- RESTART ---"] + lines
                try:
                    pre_log.unlink(missing_ok=True)
                except OSError as e:
                    # Privacy cleanup: the plaintext pre-restart log is deleted
                    # after being folded into the report. If the delete fails the
                    # file PERSISTS on disk - surface it (do not swallow silently)
                    # so the leftover is discoverable (AGENTS.md rule 5).
                    from localm.debuglog import logger
                    logger.warning(
                        "bugreport: could not delete %s after reading it (%s); "
                        "the plaintext log remains on disk", pre_log, e)
        except Exception:
            # Best-effort: prepending the pre-restart log tail is a nicety. If it
            # is missing or unreadable we just return the in-memory activity on its
            # own; never let it cost us the rest of the report.
            pass
        return lines
    except Exception:
        return []


def _client_lines(client: dict) -> list:
    """Render the GUI-supplied browser context (user agent, page, viewport, recent
    console errors) for the report. All values are treated as untrusted text."""
    lines = []
    for field, label_ in (("userAgent", "User agent"), ("page", "Page"),
                          ("viewport", "Viewport"), ("appVersion", "GUI build")):
        val = client.get(field)
        if val:
            lines.append(f"- {label_}: {_scrub_secrets(str(val))[:300]}")
    console_errs = client.get("console")
    if isinstance(console_errs, list) and console_errs:
        rendered = "\n".join(_scrub_secrets(str(e)) for e in console_errs[-40:])
        lines += ["", "Recent browser console errors:", "```", rendered[-3000:], "```"]
    return lines


def save_report(text: str, when: Optional[str] = None) -> Optional[Path]:
    """Write the report to the data dir and return its path (or None on failure).
    *when* is a caller-supplied timestamp string (kept injectable for tests)."""
    try:
        from localm.config import home_dir
        base = home_dir() / "bug-reports"
    except Exception:
        # Last-resort fallback (config import failed): stay CONTAINED inside the
        # install, never a shared ~/.localm outside it.
        base = Path(__file__).resolve().parents[1] / "home" / "bug-reports"
    try:
        base.mkdir(parents=True, exist_ok=True)
        if when is None:
            import time
            when = time.strftime("%Y%m%d-%H%M%S")
        path = base / f"bug-{when}.md"
        path.write_text(text, encoding="utf-8")
        # The report carries environment diagnostics and a traceback; on a
        # multi-user box it should not be world-readable. chmod is a no-op on
        # Windows, so this is safe cross-platform.
        try:
            path.chmod(0o600)
        except OSError:
            # Best-effort hardening. chmod is a no-op on Windows and only fails on
            # POSIX filesystems that do not support per-file perms (e.g. a FAT or
            # network mount), where the data dir's own perms still apply. Proven
            # low-risk regardless: the report deliberately carries NO secrets (no
            # API key, env, config secrets, or chat content - see module docstring),
            # so a world-readable report leaks nothing sensitive.
            pass
        return path
    except Exception:
        return None


def save_user_report(description: str, *, summary: str = "",
                     include_log: bool = False,
                     client: Optional[dict] = None) -> Optional[Path]:
    """Build and save a USER-initiated bug report and return its path (R47).

    The shared backend for the GUI "Report a bug" control and the
    ``localm bug-report`` CLI: the user's *description* fills the "What I was
    doing" section, the safe environment snapshot is collected as usual (now incl.
    loaded model, effective backend, session mode, a safe config subset, key
    dependency versions, and the in-memory recent-activity log), and with
    *include_log* the current run's on-disk debug log tail is attached
    (home-scrubbed at source - never the API key, config secrets, or chat data).
    *client* is an optional GUI-supplied browser context (user agent, page,
    viewport, recent JS console errors). Returns None on a write failure (the
    caller surfaces that rather than reporting a false success)."""
    description = (description or "").strip()
    if not summary:
        summary = description.splitlines()[0] if description else ""
    summary = summary.strip()[:120] or "user-reported issue"
    context: dict = {"operation": "gui-bug-report"}
    if include_log:
        import os
        tail = _recent_log_tail(pid=os.getpid())
        if tail:
            context["recent_log_tail"] = tail
    # Always attach a hang trace captured by THIS run (independent of
    # include_log): it only exists if the server actually froze, and it is the
    # single most useful thing for diagnosing a "the app hung" report. Scoped to
    # our own pid like the log tail above: an old freeze from a previous run is
    # not this report's problem, and presenting one as the diagnosis is worse
    # than attaching nothing (REG-542).
    import os as _os
    hang = _recent_hang_traces(pid=_os.getpid())
    if hang:
        context["hang_traces"] = hang
    if isinstance(client, dict) and client:
        context["client"] = client
    text = build_report(summary, context=context)
    if description:
        # Drop the user's own words into the otherwise-empty "What I was doing".
        # Scrub here: this is inserted AFTER build_report's own scrub pass and is
        # uploaded verbatim in the report body when the user picks upload, so it must
        # be scrubbed at this injection point too (HON-15).
        text = text.replace(
            "<!-- Please describe what you ran and what you expected. -->",
            _scrub_secrets(description))
    return save_report(text)


def _truncate_body(body: str) -> str:
    if len(body) <= _MAX_PREFILL_BODY:
        return body
    return body[:_MAX_PREFILL_BODY] + "\n\n... (truncated - see the saved report file)"


def mailto_url(summary: str, body: str) -> str:
    q = urllib.parse.urlencode(
        {"subject": f"localm bug: {summary}", "body": _truncate_body(body)},
        quote_via=urllib.parse.quote)
    return f"mailto:{MAINTAINER_EMAIL}?{q}"


# --------------------------------------------------------------------------- #
#  Upload channel: file the report as a GitHub issue WITHOUT a tester account  #
#                                                                              #
#  The app POSTs the (user-reviewed) report to a configured endpoint - the     #
#  localm bug-report proxy, a small Cloudflare Worker that holds a fine-grained #
#  GitHub token SERVER-SIDE and creates the issue. No token ships in the app,   #
#  the token can only file issues through the rate-limited proxy (never read    #
#  the repo), and it rotates at the proxy without re-shipping. See              #
#  tools/bugreport-proxy/. Uploading is ALWAYS explicit (a user action), never  #
#  automatic - a crash report is only saved to a file.                         #
# --------------------------------------------------------------------------- #

def upload_config() -> tuple:
    """(url, token) for the upload channel from config, or (None, None) when not
    configured. The token is an optional shared secret. Never raises."""
    try:
        from localm.config import load_config
        cfg = load_config()
        url = (cfg.get("bugreport_upload_url") or "").strip() or None
        token = (cfg.get("bugreport_upload_token") or "").strip() or None
        return url, token
    except Exception:
        return None, None


def upload_available() -> bool:
    """True when an upload endpoint is configured (the GUI uses this to decide
    whether to offer a 'Send to maintainer' button)."""
    return upload_config()[0] is not None


def _retry_after_from(headers, body_text) -> int:
    """Best-effort retry delay (seconds) for a 429: the ``Retry-After`` response
    header, else a ``retry_after`` field in the JSON body, else a 30s default."""
    val = None
    try:
        if headers is not None:
            val = headers.get("Retry-After")
    except Exception:
        # Header access is best-effort; a missing/odd header just falls through to
        # the body/default below - never let it break the (already-failed) upload.
        val = None
    if val:
        try:
            return max(1, int(str(val).strip()))
        except (TypeError, ValueError):
            pass
    if body_text:
        try:
            import json as _json
            obj = _json.loads(body_text)
            if isinstance(obj, dict) and obj.get("retry_after"):
                return max(1, int(obj["retry_after"]))
        except Exception:
            # A non-JSON or malformed body simply yields the default delay.
            pass
    return 30


def _classify_url_error(exc) -> tuple:
    """(stage, hint) diagnosing WHERE a failed upload broke, from the ACTUAL error
    only - we never contact a third-party host to test connectivity (offline-first
    + privacy). ``stage`` is offline_or_dns / tls / timeout / unreachable / unknown;
    ``hint`` is a friendly, actionable line (the caller adds the "report is saved /
    email it" part)."""
    import socket
    import ssl

    # A urllib URLError wraps the real cause in .reason (usually an OSError); unwrap
    # so isinstance checks see gaierror/SSLError/timeout, not the URLError shell.
    reason = getattr(exc, "reason", None)
    inner = reason if isinstance(reason, BaseException) else exc

    if isinstance(inner, socket.gaierror):
        return ("offline_or_dns",
                "Could not look up the bug-report server's address. You may be "
                "offline, or a DNS/network setting is blocking the connection.")
    if isinstance(inner, ssl.SSLError):
        return ("tls",
                "A secure (TLS) connection to the bug-report server could not be "
                "established.")
    if isinstance(inner, (TimeoutError, socket.timeout)):
        return ("timeout",
                "The bug-report server did not respond in time. It may be slow or "
                "temporarily unreachable.")
    if isinstance(inner, ConnectionError):
        return ("unreachable",
                "Reached the network but could not connect to the bug-report "
                "server. It may be down, or a firewall/proxy is blocking it.")
    if isinstance(inner, OSError):
        txt = str(getattr(inner, "strerror", "") or inner).lower()
        if "unreachable" in txt or "not known" in txt or "no address" in txt:
            return ("offline_or_dns",
                    "The network appears to be unavailable (could not reach the "
                    "bug-report server). Check your internet connection.")
        return ("unreachable",
                "Could not connect to the bug-report server. It may be down, or a "
                "firewall/proxy is blocking it.")
    return ("unknown",
            "The report could not be sent for an unexpected reason.")


def upload_report(title: str, body: str, *, url: Optional[str] = None,
                  token: Optional[str] = None, timeout: float = 15.0,
                  opener=None) -> dict:
    """POST a user-reviewed report to the upload endpoint and return its JSON
    response (e.g. ``{"url": "<issue url>"}``).

    Only the report text (plus an optional shared secret) is sent; the GitHub
    token lives at the proxy. Raises :class:`LocalmError` on any failure - no
    endpoint, a network error, or a non-2xx response - so a failed send is NEVER
    reported as success (we do not hide problems). *opener* is injectable for
    tests (defaults to urllib)."""
    import json as _json

    # Scrub the title at the upload boundary: it becomes a PUBLIC GitHub issue
    # title, and callers pass the user's raw summary / description first line
    # (report_failure, inference/routes/admin.py). This is the single choke point
    # every uploaded title flows through, so scrubbing here covers all callers - a
    # future one cannot forget (HON-03/HON-15). Idempotent; no-ops on empty text.
    title = _scrub_secrets(title)

    # Fill each of url/token from config independently when not explicitly passed,
    # so an explicit token does not suppress loading the url from config (and vice
    # versa).
    if url is None or token is None:
        cfg_url, cfg_token = upload_config()
        if url is None:
            url = cfg_url
        if token is None:
            token = cfg_token
    if not url:
        raise LocalmError("no upload endpoint is configured",
                          reason="set bugreport_upload_url to enable the Send channel",
                          stage="no_endpoint",
                          hint="No bug-report server is configured in this build, so "
                               "the report cannot be filed automatically.")
    payload = _json.dumps(
        {"title": (title or "localm bug report")[:200], "body": body or ""}
    ).encode("utf-8")
    headers = {"Content-Type": "application/json", "User-Agent": "localm-bugreport"}
    if token:
        headers["X-Localm-Token"] = token

    if opener is None:
        import urllib.error
        import urllib.request

        from localm.http_ssl import verified_urlopen

        def opener(u, data, hdrs, to):  # noqa: E306
            req = urllib.request.Request(u, data=data, headers=hdrs, method="POST")
            try:
                # verified_urlopen (see localm/http_ssl.py): this is the very path
                # the setup-llama failure message tells the user to use to report
                # it, so it must work under the same conditions setup-llama does.
                with verified_urlopen(req, timeout=to) as resp:
                    return resp.status, resp.read().decode("utf-8", "replace")
            except urllib.error.HTTPError as e:
                detail = ""
                try:
                    detail = e.read().decode("utf-8", "replace")[:300]
                except Exception:
                    # The error body is best-effort extra context; if it cannot be
                    # read we still raise the failure below (with an empty detail),
                    # so the rejection is never hidden.
                    pass
                if e.code == 429:
                    raise RateLimitedError(
                        _retry_after_from(getattr(e, "headers", None), detail),
                        reason=detail)
                raise LocalmError(
                    "the bug-report server rejected the upload",
                    reason=f"HTTP {e.code}: {detail}".strip(),
                    stage="server_rejected",
                    hint=(f"The bug-report server received the report but rejected it "
                          f"(HTTP {e.code}). This is likely a temporary server-side "
                          f"issue, not your connection."))
            except (urllib.error.URLError, OSError) as e:
                stage, hint = _classify_url_error(e)
                raise LocalmError("could not reach the bug-report server",
                                  reason=str(getattr(e, "reason", e)),
                                  stage=stage, hint=hint)

    status, raw = opener(url, payload, headers, timeout)
    if int(status) == 429:
        raise RateLimitedError(_retry_after_from(None, raw), reason=str(raw)[:300])
    if not (200 <= int(status) < 300):
        raise LocalmError(
            "the bug-report server rejected the upload",
            reason=f"HTTP {status}: {raw[:300]}".strip(),
            stage="server_rejected",
            hint=(f"The bug-report server rejected the report (HTTP {status}). This is "
                  f"likely a temporary server-side issue, not your connection."))
    try:
        return _json.loads(raw) if raw.strip() else {}
    except ValueError:
        return {"raw": raw[:300]}


def report_failure(*, summary: str, reason: str = "",
                   error: Optional[BaseException] = None,
                   context: Optional[dict] = None,
                   interactive: bool = True,
                   assume_yes: bool = False,
                   auto_send: bool = False,
                   as_failure: bool = True,
                   open_browser=webbrowser.open,
                   prompt=None) -> Optional[Path]:
    """Say sorry (what + why), save an editable report, and offer to send it.

    Returns the saved report path (or None). ``interactive`` False (or
    ``assume_yes``) saves and points at the file without prompting or opening a
    browser - the right behaviour for unattended / scripted runs. ``as_failure``
    False is for a user-initiated report (``localm bug-report``): neutral header,
    no apology. ``auto_send`` True uploads immediately via the account-less proxy
    channel (no menu, no browser) - the caller's own explicit consent (e.g. the
    ``--send`` flag) stands in for picking option [1] interactively, so this is
    still an explicit user action, not automatic reporting. ``open_browser`` and
    ``prompt`` are injectable for tests."""
    console.print()
    if as_failure:
        console.print(f"[bold red]Sorry - {summary}.[/bold red]")
        if reason:
            console.print(f"[red]Reason:[/red] {reason}")
    else:
        console.print(f"[bold]Filing a bug report:[/bold] {summary}")
        if reason:
            console.print(f"[dim]{reason}[/dim]")

    text = build_report(summary, reason=reason, error=error, context=context)
    path = save_report(text)
    if path is not None:
        console.print(f"[dim]A bug report was saved (edit it before sending):[/dim] {path}")
    else:
        console.print("[yellow]Could not save a report file; you can still copy the "
                      "details above.[/yellow]")

    up_url, up_token = upload_config()
    can_upload = up_url is not None

    if auto_send:
        body = path.read_text(encoding="utf-8") if path is not None else text
        where = str(path) if path is not None else "the text above"
        if not can_upload:
            console.print("[yellow]No hosted send channel is configured - the report is "
                          f"saved at {where}; email it to {MAINTAINER_EMAIL} instead.[/yellow]")
            return path
        try:
            res = upload_report(summary, body, url=up_url, token=up_token)
        except RateLimitedError as e:
            import time as _time
            console.print(f"[yellow]Rate limited. Retrying in {e.retry_after}s...[/yellow]")
            _time.sleep(e.retry_after)
            try:
                res = upload_report(summary, body, url=up_url, token=up_token)
            except LocalmError as e2:
                console.print(f"[yellow]Still could not send it.[/yellow] "
                              f"{e2.hint or e2.reason}")
                console.print(f"[dim]The report is at {where} - email it to "
                              f"{MAINTAINER_EMAIL} instead.[/dim]")
                return path
        except LocalmError as e:
            console.print(f"[yellow]Could not send it.[/yellow] {e.hint or e.reason}")
            console.print(f"[dim]The report is at {where} - email it to "
                          f"{MAINTAINER_EMAIL} instead.[/dim]")
            return path
        link = res.get("url") if isinstance(res, dict) else None
        console.print("[green]Sent to the maintainer.[/green]"
                      + (f" Tracking issue: {link}" if link else ""))
        return path

    if not interactive or assume_yes:
        if can_upload:
            console.print(
                "[dim]Run[/dim] [bold]localm bug-report --send[/bold] [dim]to send it now "
                "(no GitHub account needed) - or email/Discord it yourself.[/dim]")
        else:
            console.print(f"[dim]Send it to the maintainer ({MAINTAINER_EMAIL}) by email or "
                          "Discord.[/dim]")
        return path

    # Re-read the saved file so the user's edits (made before picking a channel)
    # are what actually gets sent - otherwise "edit it first" would be a lie.
    body = text
    if path is not None:
        try:
            body = path.read_text(encoding="utf-8")
        except OSError:
            body = text

    console.print("How would you like to send it (edit the file first if you want)?")
    # Map the displayed number -> action, so an extra "send now" option when an
    # upload endpoint is configured does not renumber the always-present channels
    # (email is [2], self [3] regardless of the upload option).
    actions = {}
    if can_upload:
        console.print("  [1] Send to the maintainer now  "
                      "[dim](uploads the report - no GitHub account needed)[/dim]")
        actions["1"] = "upload"
    console.print("  [2] Email the maintainer  [dim](opens your mail app, works anywhere)[/dim]")
    console.print(f"  [3] I'll send it myself   [dim](Discord / email to {MAINTAINER_EMAIL})[/dim]")
    console.print("  [Enter] not now")
    actions.update({"2": "email", "3": "self"})

    ask = prompt
    if ask is None:
        import click
        def ask(text_):  # noqa: E306
            return click.prompt(text_, default="", show_default=False)
    choice = (ask("  Pick a number") or "").strip()
    action = actions.get(choice, "none")

    # When the file save failed (path is None) the channels still work off the
    # in-memory text, but messages must not claim a file exists - say where the
    # report actually is, honestly ("we do not hide problems").
    where = (str(path) if path is not None
             else "the text above (it could not be saved to a file)")

    try:
        if action == "upload":
            attempt = 0
            while True:
                attempt += 1
                try:
                    res = upload_report(summary, body, url=up_url, token=up_token)
                    link = res.get("url") if isinstance(res, dict) else None
                    console.print("[green]Sent to the maintainer.[/green]"
                                  + (f" Tracking issue: {link}" if link else ""))
                    break
                except RateLimitedError as e:
                    # Rate limited: wait the server-advised delay and retry ONCE
                    # automatically rather than making the tester re-run the command.
                    import time as _time
                    msg = e.hint or "The bug-report server is rate limiting."
                    console.print(f"[yellow]{msg} Retrying in {e.retry_after}s...[/yellow]")
                    _time.sleep(e.retry_after)
                    if attempt >= 2:
                        console.print(f"[yellow]Still rate limited.[/yellow] The report "
                                      f"is at {where} - email it to {MAINTAINER_EMAIL}.")
                        break
                    continue
                except LocalmError as e:
                    # A failed send must never look like success - say WHERE it failed
                    # (rule 5), keep the file, and offer to retry creating the issue.
                    console.print(f"[yellow]Could not send it.[/yellow] {e.hint or e.reason}")
                    console.print(f"[dim]The report is saved at {where}.[/dim]")
                    if attempt >= 3:
                        console.print(f"[dim]Email it to {MAINTAINER_EMAIL} when you can.[/dim]")
                        break
                    again = (ask("  Retry sending now? [y/N]") or "").strip().lower()
                    if again in ("y", "yes"):
                        continue
                    console.print(f"[dim]Not retried - email {where} to "
                                  f"{MAINTAINER_EMAIL} when you can.[/dim]")
                    break
        elif action == "email":
            open_browser(mailto_url(summary, body))
            console.print(f"[green]Opened your mail app to {MAINTAINER_EMAIL}.[/green]")
        elif action == "self":
            console.print(f"[dim]Thanks. Send {where} to {MAINTAINER_EMAIL} or on Discord "
                          "when you can.[/dim]")
        else:
            console.print("[dim]No report sent. It is saved if you change your mind.[/dim]")
    except Exception:
        console.print("[yellow]Could not open that automatically - the report is at "
                      f"{where}.[/yellow]")
    return path


# --------------------------------------------------------------------------- #
#  Process-wide net: catch a bug ANYWHERE, not just in a CLI command           #
#                                                                              #
#  Bugs are not confined to setup. A crash in a background thread (model       #
#  preload, the jobs runner, the coder loop) used to die silently; an uncaught #
#  main-thread exception used to dump a raw traceback. These hooks make every  #
#  Python-level failure route through the same "sorry X for Y" + report path.  #
#                                                                              #
#  Honest limit: this catches PYTHON exceptions. A native crash inside         #
#  llama.dll (segfault), an OS OOM-kill, or os._exit cannot be caught in-       #
#  process - that needs subprocess isolation, a separate effort.               #
# --------------------------------------------------------------------------- #

_handlers_installed = False


def _handle_main_exception(exc_type, exc, tb) -> None:
    """sys.excepthook: last-resort net for an uncaught main-thread exception.
    Ctrl+C stays quiet; everything else becomes a friendly report. Fully guarded:
    if reporting itself fails, defer to the interpreter's default hook."""
    if issubclass(exc_type, KeyboardInterrupt):
        sys.__excepthook__(exc_type, exc, tb)
        return
    try:
        interactive = bool(getattr(sys.stdin, "isatty", lambda: False)())
        report_failure(
            summary=getattr(exc, "summary", None) or "localm hit an unexpected error",
            reason=getattr(exc, "reason", None) or str(exc),
            error=exc, context=getattr(exc, "context", None) or {},
            interactive=interactive)
    except Exception:
        sys.__excepthook__(exc_type, exc, tb)


def _handle_thread_exception(args) -> None:
    """threading.excepthook: a crash in a background thread used to vanish. Log it
    and save a report (never prompt - a worker thread has no user attention), so a
    failure is visible without taking the whole app down."""
    exc = getattr(args, "exc_value", None)
    if exc is None or isinstance(exc, SystemExit):
        return
    try:
        tname = getattr(getattr(args, "thread", None), "name", "?")
        report_failure(
            summary=f"a background task crashed (thread '{tname}')",
            reason=str(exc), error=exc, context={"thread": tname},
            interactive=False)
    except Exception:
        try:
            threading.__excepthook__(args)
        except Exception:
            # Last resort: the bug reporter itself failed AND the stdlib default
            # hook failed. There is nothing left to fall back to, and an
            # excepthook must not raise (it would mask the original crash), so
            # there is genuinely nothing safe to do but swallow here.
            pass


def install_global_handlers(force: bool = False) -> bool:
    """Install the process-wide graceful-failure net (main thread + background
    threads). Idempotent. A no-op under pytest unless *force* (so the test runner
    keeps its own exception/thread handling). Returns True if it installed."""
    global _handlers_installed
    if _handlers_installed:
        return False
    if not force and "pytest" in sys.modules:
        return False
    sys.excepthook = _handle_main_exception
    threading.excepthook = _handle_thread_exception
    _handlers_installed = True
    return True


# --------------------------------------------------------------------------- #
#  asyncio + native-crash net (SRV-3): "fire the bug reporter no matter what"  #
#                                                                              #
#  The excepthooks above cover the main thread and background threads, but two #
#  failure modes still escaped: (1) an uncaught exception inside an asyncio    #
#  task (uvicorn's event loop) only logs "Task exception was never retrieved"; #
#  (2) a NATIVE crash (a C-extension segfault, an OS kill, or a force-closed   #
#  console window) cannot be caught in-process at all. We close (1) with an    #
#  asyncio exception handler and (2) with a crash marker: the server arms a    #
#  marker on start and disarms it on a clean shutdown, so a marker still       #
#  present on the NEXT start means the previous run died hard - and we file the #
#  report then, with the native traceback faulthandler captured.               #
# --------------------------------------------------------------------------- #

_crash_trace_fh = None   # kept alive so faulthandler can write to it


def install_asyncio_handler(loop) -> bool:
    """Route an uncaught asyncio task/loop exception through the bug reporter
    (saved, never prompted - a server loop has no user at the keyboard). Returns
    True if installed. Non-exception loop messages fall through to the default."""
    import asyncio
    try:
        def _h(loop, ctx):
            exc = ctx.get("exception")
            if isinstance(exc, (KeyboardInterrupt, SystemExit,
                                asyncio.CancelledError)):
                return   # normal control flow, not a crash
            if exc is None:
                loop.default_exception_handler(ctx)   # message-only: keep default
                return
            try:
                report_failure(
                    summary="an async task crashed",
                    reason=ctx.get("message") or str(exc),
                    error=exc, context={"asyncio": ctx.get("message", "")},
                    interactive=False)
            except Exception:
                loop.default_exception_handler(ctx)
        loop.set_exception_handler(_h)
        return True
    except Exception:
        return False


def _crash_dir(home=None):
    from pathlib import Path
    if home is None:
        from localm.config import HOME_DIR
        home = HOME_DIR
    d = Path(home) / "run"
    d.mkdir(parents=True, exist_ok=True)
    return d


# Running more than one localm server against the SAME LOCALM_HOME is a
# first-class, supported scenario (`localm ps` lists "running localm servers
# (per-directory instances)"; `serve --project/--new/--isolated`; the coder
# plugin self-starting its own backing server). The marker used to be one
# unscoped file per home, so a second instance starting up would find the
# FIRST instance's still-armed marker, misread it as "the previous run died
# hard", and file a spurious crash report about a server that was never down -
# and its own later clean-shutdown disarm would then delete whatever marker
# existed at that point, which could by then belong to a THIRD, still-live
# instance, silencing a real crash of that instance forever. Scoping the
# marker (and its companion native-fault-trace file) per instance_id - the
# same per-process identity instances.py's own registry already uses for
# exactly this reason (``run/<instance_id>.json``) - means each running
# instance only ever arms, reports, and disarms its OWN file.


def _crash_marker_path(d, instance_id: Optional[str]):
    if instance_id:
        return d / f"server-crash.{instance_id}.marker"
    # No instance identity available (a bare create_app() test harness that
    # never went through instances.advertise()): fall back to the legacy
    # shared name rather than silently skipping the crash guard.
    return d / "server-crash.marker"


def _crash_trace_path(d, instance_id: Optional[str]):
    if instance_id:
        return d / f"server-crash-trace.{instance_id}.txt"
    return d / "server-crash-trace.txt"


def _trace_path_for_marker(d, marker):
    """The native-fault-trace file that belongs WITH *marker* (same instance),
    derived from the marker's own filename rather than a second parameter, so a
    caller iterating markers it did not itself name (check_and_report_prior_crash)
    never has to keep the two paths in sync by hand."""
    name = marker.name
    prefix, suffix = "server-crash.", ".marker"
    if name.startswith(prefix) and name.endswith(suffix) and name != "server-crash.marker":
        return d / f"server-crash-trace.{name[len(prefix):-len(suffix)]}.txt"
    return d / "server-crash-trace.txt"


def _all_crash_markers(d):
    """Every armed marker under *d*: one per instance that has ever armed
    against this LOCALM_HOME (plus the legacy unscoped name, if present)."""
    markers = list(d.glob("server-crash.*.marker"))
    legacy = d / "server-crash.marker"
    if legacy.exists():
        markers.append(legacy)
    return markers


def arm_crash_guard(context: Optional[dict] = None, home=None,
                    instance_id: Optional[str] = None) -> bool:
    """Mark that a server run is in progress and enable faulthandler so a native
    fault leaves a trace. If the process dies hard the marker survives;
    check_and_report_prior_crash() reports it on the next start. *instance_id*
    (``app.state.instance_id``, set by instances.advertise() before this is
    called) scopes the marker to THIS running instance so a sibling instance
    sharing the same LOCALM_HOME is never mistaken for a crash - see the module
    note above. Returns True if armed. Fully guarded - never raises into the
    caller."""
    global _crash_trace_fh
    import faulthandler
    import json
    import os
    try:
        d = _crash_dir(home)
        _crash_trace_fh = open(_crash_trace_path(d, instance_id), "w", encoding="utf-8")
        try:
            faulthandler.enable(file=_crash_trace_fh, all_threads=True)
        except Exception:
            # Best-effort: if faulthandler cannot attach (e.g. the fd is not a
            # real file on some platforms) we still arm the crash marker below, so
            # a hard death is still reported next start - just without the native
            # traceback. Arming must not fail over this.
            pass
        _crash_marker_path(d, instance_id).write_text(
            json.dumps({"pid": os.getpid(), "context": context or {}}),
            encoding="utf-8")
        return True
    except Exception:
        return False


def disarm_crash_guard(home=None, instance_id: Optional[str] = None) -> None:
    """Clean shutdown: drop THIS instance's own marker (never a sibling's) so
    the next start does not report a crash. *instance_id* must be the SAME id
    passed to the matching arm_crash_guard() call - see the module note above
    for why an unscoped delete is unsafe when more than one instance shares a
    LOCALM_HOME."""
    global _crash_trace_fh
    import faulthandler
    try:
        d = _crash_dir(home)
        _crash_marker_path(d, instance_id).unlink(missing_ok=True)
    except Exception:
        # Best-effort cleanup on a CLEAN shutdown. Worst case the marker survives
        # and the next start files one spurious "prior crash" report - annoying,
        # not unsafe. disarm must not raise during shutdown.
        pass
    try:
        if _crash_trace_fh is not None:
            faulthandler.disable()
            _crash_trace_fh.close()
            _crash_trace_fh = None
    except Exception:
        # Best-effort: releasing the faulthandler file on shutdown. A failure
        # leaks a file handle until process exit (imminent anyway); never raise.
        pass


def _report_one_crash_marker(d, marker, home, interactive: bool):
    """Report *marker* as a crash IF its recorded pid is no longer alive, then
    clear it. Returns the report path, or None if this marker was skipped (a
    live sibling instance) or nothing could be filed. Never raises."""
    import json
    from localm.instances import pid_alive
    try:
        if not marker.exists():
            return None
        info = {}
        try:
            info = json.loads(marker.read_text(encoding="utf-8"))
        except Exception:
            # A corrupt/half-written marker (the process may have died mid-write)
            # still means a crash happened: fall back to empty context and report
            # it anyway rather than dropping the crash on the floor.
            pass
        pid = info.get("pid")
        try:
            if pid_alive(int(pid)):
                # The recorded pid is still running: this is a SIBLING instance
                # that is simply still up, not a crash (SRV-3 follow-up). Leave
                # its marker alone - its own eventual disarm (clean exit) or a
                # future check here (real crash) will handle it correctly. PID
                # reuse is an accepted residual risk here, same as elsewhere in
                # this codebase (e.g. instances.py) - no whoami-style identity
                # check is recorded in the marker to rule it out.
                return None
        except (TypeError, ValueError):
            # No/unparseable pid recorded: cannot confirm liveness, so treat it
            # like the corrupt-marker case above - report rather than drop it.
            pass
        trace = ""
        try:
            tp = _trace_path_for_marker(d, marker)
            if tp.exists():
                trace = tp.read_text(encoding="utf-8").strip()
        except Exception:
            # Best-effort: the native traceback file is optional extra context.
            # If unreadable we report the crash without it rather than not at all.
            pass
        # Clear FIRST so a failure while reporting cannot loop the marker forever.
        try:
            marker.unlink(missing_ok=True)
        except Exception:
            # If the marker cannot be removed the next start may re-report this
            # same crash (a duplicate, not a lost one). Tolerable; do not abort the
            # report we are about to file over a failed unlink.
            pass
        ctx = {"prior_run": info}
        if trace:
            ctx["native_trace"] = trace[:4000]
        # Attach the crashed run's own log tail (matched by pid) so the report is
        # actionable even with no native trace (window-close / OS-kill leave none).
        tail = _recent_log_tail(home, pid=info.get("pid"))
        if tail:
            ctx["recent_log_tail"] = tail
        # If the watchdog captured a freeze before the run was force-killed, attach
        # its stacks too: a hang the user force-quit is exactly this recovery path.
        # The CRASHED run's freeze, matched by its pid like the log tail above -
        # not this recovering process's, and not some unrelated older one.
        hang = _recent_hang_traces(home, pid=info.get("pid"))
        if hang:
            ctx["hang_traces"] = hang
        return report_failure(
            summary="localm server crashed (recovered on the next start)",
            reason=("the previous server run ended without a clean shutdown - a "
                    "native crash, an OS kill, or a force-closed window"),
            error=None, context=ctx, interactive=interactive)
    except Exception:
        return None


def check_and_report_prior_crash(home=None, interactive: bool = False):
    """Scan every crash marker left under this LOCALM_HOME's run/ dir (one per
    instance that has ever armed here) and report+clear any whose recorded pid
    is no longer alive - a hard crash: a native fault, an OS kill, or a
    force-closed window. A marker whose pid IS still alive is a sibling
    instance simply still running (see the per-instance-scoping module note
    above) and is left untouched: not reported, not deleted. Returns the last
    report path filed, or None if nothing was reported. Never raises into the
    caller."""
    try:
        d = _crash_dir(home)
        markers = _all_crash_markers(d)
    except Exception:
        return None
    filed = None
    for marker in markers:
        result = _report_one_crash_marker(d, marker, home, interactive)
        if result is not None:
            filed = result
    return filed
